import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: string;
}

const themes: Array<{ value: ThemeValue; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const fonts = [
  { value: 'sans', label: 'Inter Tight', meta: 'sans-serif' },
  { value: 'display', label: 'Fraunces', meta: 'serif' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'monospace' },
];

const initialSettings: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'sans',
};

export default function AppearanceSettingsScreen({
  onChange,
}: {
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>(initialSettings);

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel = themes.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <JxToggle
        items={themes}
        value={settings.theme}
        onValueChange={(value) => update({ theme: value as ThemeValue })}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={fonts}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

